source:
(()=>{
/* Bài 5 — Ôn tập trước KTTX2 (chuẩn tường minh, 19/10/2026). Không có kiến thức mới.
   Bối cảnh: tổng kết quầy trà sữa của lớp sau Lễ hội Mùa Xuân.
   Tiết 1 = Chặng 1 (ôn cout, biến, cin), tiết 2 = Chặng 2 (ôn if–else, for, cộng dồn) + Chặng chứng chỉ, rồi KTTX2 trên Canvas.
   Mỗi chặng 6 tab (VAN_PHONG.md): Bối cảnh → Đoán rồi chạy → Kiểm chứng → Ghi nhớ → Luyện tập → Phản tư.
*/
"use strict";

const { scratch, boiCanh, bang, ghiVo, luuY, chiTiet, timThem, sauTab, huongDanDoan, bonBuoc, tuCham, kieuDuLieu } = window.KIT;
const strip = code => window.CPP.stripComments(code);
const khung = than => `#include <iostream>\nusing namespace std;\nint main() {\n${than}\n    return 0;\n}`;

/* ---------- Chặng 1: cout, biến, cin ---------- */
const HOA_DON = khung(`    cout << "HOA DON" << endl;
    cout << "Tra sua x " << 2 << endl;
    cout << "Thanh tien: " << 2 * 25000 << " dong";`);
const MAN_HOA_DON = ["HOA DON\nTra sua x 2\nThanh tien: 50000 dong", "HOA DONTra sua x 2Thanh tien: 50000 dong",
  "HOA DON\nTra sua x 2\nThanh tien: 2 * 25000 dong", "HOA DON\nTra sua x2\nThanh tien:50000dong"];
const GAN_LAI = khung(`    int soLy = 3;
    int tongTien = soLy * 20000;
    soLy = soLy + 1;
    cout << "So ly: " << soLy << endl;
    cout << "Tong tien: " << tongTien;`);
const MAN_GAN = ["So ly: 4\nTong tien: 60000", "So ly: 4\nTong tien: 80000", "So ly: 3\nTong tien: 60000", "So ly: soLy\nTong tien: tongTien"];
const HOI_SO_LY = khung(`    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    cout << "Tong tien: " << soLy * 20000;`);
const manHoi = n => `Nhap so ly: ${n}\nTong tien: ${n * 20000}`;
const LOI_C1 = khung(`    int soLy;
    cout << "Nhap so ly: ";
    cin >> soly;
    cout << "Tong tien: " << soLy * 20000;`);
const TRA_DAO_KHUNG = khung(`    int soLy;
    // 1. In cau dan "Nhap so ly: " roi nhap soLy

    // 2. In "So ly: " va soLy, xuong dong

    // 3. In "Tong tien: " va soLy * 20000
`);

/* ---------- Chặng 2: if–else, for, cộng dồn ---------- */
const QUA = khung(`    int soLy;
    cout << "Nhap so ly: ";
    cin >> soLy;
    if (soLy >= 5) {
        cout << "Tang banh" << endl;
    } else {
        cout << "Tang keo" << endl;
    }
    cout << "Cam on!";`);
const manQua = (n, qua) => `Nhap so ly: ${n}\n${qua}Cam on!`;
const DOANH_THU = khung(`    int n;
    cout << "Nhap so don: ";
    cin >> n;
    int tong = 0;
    for (int i = 1; i <= n; i++) {
        tong = tong + 20000;
    }
    cout << "Doanh thu: " << tong;`);
const NHAN = khung(`    for (int i = 1; i <= 3; i++) {
        cout << "Don " << i << endl;
    }
    cout << "Het don";`);
const VE_KHUNG = khung(`    int n;
    cout << "Nhap so luot: ";
    cin >> n;
    int tong = 0;
    // Vong lap: moi luot in "Luot i: ", nhap soVe, cong soVe * 15000 vao tong

    cout << "Tong tien: " << tong << endl;
    // if - else: tu 60000 in "Nhan qua", con lai in "Chua du"
`);
const CUOI_NGAY_KHUNG = khung(`    int n;
    cout << "Nhap so don: ";
    cin >> n;
    int tong = 0;
    // Vong lap: moi don in "Don i: ", nhap soLy, cong soLy * 20000 vao tong

    // In "Doanh thu: " va tong, xuong dong
    // if - else: tu 100000 in "Dat chi tieu", con lai in "Chua dat"
`);

const BON_BUOC = bonBuoc([["Hiểu đề", "nhập gì, tính gì, in ra những dòng nào? Quy tắc có mốc nào không?"],
  ["Chọn biến", "biến nhận số nhập, biến tổng (khởi tạo 0 trước vòng lặp), kiểu <code>int</code>, tên camelCase."],
  ["Thiết kế test case trước khi viết", "dưới mốc, đúng mốc, trên mốc; với vòng lặp thử thêm n = 0 và n = 1."],
  ["Viết, chạy, so sánh, sửa", "chạy với từng test case, so màn hình với kết quả đã tính tay."]]);

window.LESSON = {
  id: "bai05",
  chuan: 2,
  number: 5,
  title: "Ôn tập trước KTTX2",
  story: "Tổng kết quầy trà sữa",
  badge: { icon: "🗺️", name: "Nhà thám hiểm C++" },
  skills: ["cout và endl", "Biến int, phép gán", "cin và câu dẫn", "if–else và mốc", "Vòng lặp for", "Biến tổng"],
  certNote: "Ôn tập trước KTTX2 · làm lại không giới hạn",

  errorTable: [
    ["Lỗi cú pháp ở khoảng dòng N", "Thiếu <code>;</code> ở dòng trên, thiếu dấu <code>\"</code>, <code>( )</code> hoặc <code>{ }</code>", "Xem dòng máy báo và dòng ngay phía trên"],
    ["Máy báo không biết tên biến", "Gõ sai chữ hoa, chữ thường (<code>soly</code> và <code>soLy</code>) hoặc chưa khai báo", "Gõ tên giống hệt lúc khai báo"],
    ["Các dòng chữ dính liền nhau", "Thiếu <code>&lt;&lt; endl</code>", "Thêm <code>&lt;&lt; endl</code> ở cuối câu lệnh in dòng phía trên"],
    ["Khách đúng mốc bị xếp sai", "Nhầm <code>&gt;</code> với <code>&gt;=</code>", "Đọc kỹ “từ … trở lên” và thử đúng số mốc"],
    ["Thiếu hoặc thừa một vòng lặp", "Nhầm <code>&lt;</code> với <code>&lt;=</code>", "Thử n = 1 và đếm số dòng in ra"],
    ["Tổng sai", "Khai báo <code>int tong = 0;</code> trong thân vòng lặp", "Khai báo biến tổng ở trước vòng lặp"]
  ],

  steps: [
    /* ================= CHẶNG 1 · TIẾT 1 · cout, biến, cin ================= */
    {
      kind: "stage", id: "stage-1", number: 1, nav: "Chặng 1",
      kicker: "CHẶNG 1 · TIẾT 1 · ÔN cout, BIẾN VÀ cin",
      title: "In hoá đơn của quầy",
      bit: "Chào bạn! Chặng này ôn lại Bài 1 và Bài 2. Làm xong mỗi phần, bấm <strong>Tiếp</strong> ở cuối trang.",
      objectives: ["In đúng màn hình mong đợi bằng cout, endl, chuỗi và số",
        "Theo dõi giá trị của biến khi gán và gán lại",
        "Dùng cin có câu dẫn để nhập dữ liệu rồi tính tiền"],
      flow: [
        { label: "Bối cảnh", title: "Quầy trà sữa tổng kết lễ hội",
          html: boiCanh("Lễ hội Mùa Xuân đã xong. Trước khi làm bài kiểm tra KTTX2, lớp mình ôn lại các chương trình đã viết cho quầy trà sữa: in hoá đơn, tính tiền, hỏi số ly.",
            `<p>Chặng này không có kiến thức mới. Bạn sẽ gặp lại ba câu lệnh của Bài 1 và Bài 2: <code>cout</code> in ra màn hình, <strong>biến</strong> lưu giá trị, và <code>cin</code> nhận số người dùng gõ. Mỗi lần chạy, hãy đoán trước rồi so với máy để biết mình còn nhầm ở đâu.</p>`) + sauTab("Kiểm chứng") },
        { label: "Đoán rồi chạy", title: "Ba chương trình của quầy", tasks: ["c1-dc1", "c1-dc2", "c1-dc3"],
          html: huongDanDoan(3, true), bit: "Nhầm chỗ nào thì ghi lại, đó là chỗ cần ôn trước KTTX2." },
        { label: "Kiểm chứng", title: "Bạn còn nhớ đến đâu?", tasks: ["c1-bien", "c1-dungsai", "c1-loi"],
          code: GAN_LAI, focus: [5, 6],
          html: `<p>Khung bên trái là chương trình ở <strong>Lần 2</strong>. Dựa vào bảng Bộ nhớ bạn vừa thấy, trả lời các câu hỏi bên cạnh.</p>` },
        { label: "Ghi nhớ", title: "Ôn cout, biến và cin",
          html: ghiVo(["<code>cout &lt;&lt; \"chuỗi\" &lt;&lt; số &lt;&lt; endl;</code>: chuỗi in nguyên văn, số và phép tính được tính ra, <code>endl</code> xuống dòng.",
                "<code>int tenBien = giaTri;</code> khai báo biến; <code>tenBien = …;</code> gán lại thì giá trị cũ bị thay.",
                "<code>cout &lt;&lt; \"câu dẫn\";</code> rồi <code>cin &gt;&gt; tenBien;</code>: nhập dữ liệu từ bàn phím vào biến."])
            + luuY("biến chỉ thay đổi khi có phép gán. Ở Lần 2, <code>tongTien</code> đã tính xong ở dòng 5 nên không tự đổi khi <code>soLy</code> đổi ở dòng 6.")
            + chiTiet
            + bang("1. Bốn điều cần nhớ từ Bài 1 và Bài 2", ["Câu lệnh", "Ví dụ", "Màn hình"], [
              ["In chuỗi", "<code>cout &lt;&lt; \"Tra sua\";</code>", "<code>Tra sua</code>"],
              ["In số và phép tính", "<code>cout &lt;&lt; 2 * 25000;</code>", "<code>50000</code>"],
              ["In giá trị của biến", "<code>cout &lt;&lt; soLy;</code>", "giá trị đang lưu trong <code>soLy</code>"],
              ["Nhập số", "<code>cin &gt;&gt; soLy;</code>", "số người dùng gõ hiện ngay sau câu dẫn"]])
            + kieuDuLieu("2. ")
            + bang("3. Lỗi hay gặp", ["Lỗi", "Ví dụ", "Cách sửa"], [
              ["Thiếu <code>endl</code>", "Hai dòng in dính liền", "Thêm <code>&lt;&lt; endl</code>"],
              ["Tên biến trong dấu ngoặc kép", "<code>cout &lt;&lt; \"soLy\";</code> in chữ soLy", "Bỏ dấu ngoặc kép"],
              ["Sai chữ hoa, chữ thường", "Khai báo <code>soLy</code> nhưng gõ <code>soly</code>", "Gõ tên giống hệt lúc khai báo"],
              ["Quên câu dẫn", "Màn hình trống khi chờ nhập", "In câu dẫn ngay trước <code>cin</code>"]])
            + timThem([["https://www.w3schools.com/cpp/cpp_output.asp", "W3Schools · In ra màn hình"],
                       ["https://www.w3schools.com/cpp/cpp_variables.asp", "W3Schools · Biến"],
                       ["https://www.w3schools.com/cpp/cpp_user_input.asp", "W3Schools · Nhập dữ liệu"]]) },
        { label: "Luyện tập", title: "Điền, rồi tự viết hoá đơn trà đào", tasks: ["c1-dien", "c1-viet"], html: BON_BUOC },
        { label: "Phản tư", title: "Bạn đã chắc đến đâu?", tasks: ["c1-tucham"], stop: true,
          html: `<p>${tuCham}</p>`, bit: "Xong Chặng 1! Dừng lại và nhìn lên bảng." }
      ],
      challenges: [
        { id: "c1-dc1", type: "doanchay", predict: true, icon: "🔮",
          title: "Lần 1 · In hoá đơn",
          prompt: "Chương trình in hoá đơn 2 ly trà sữa, mỗi ly 25000 đồng. Dòng 6 nối chuỗi, phép tính và chuỗi bằng <code>&lt;&lt;</code>.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: HOA_DON, focus: [6], options: MAN_HOA_DON, answer: MAN_HOA_DON[0],
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
            { l: 4, out: "HOA DON\n", why: "In chuỗi <code>\"HOA DON\"</code> rồi <code>endl</code> xuống dòng." },
            { l: 5, out: "Tra sua x 2\n", why: "In chuỗi <code>\"Tra sua x \"</code> (có dấu cách ở cuối), số 2, rồi xuống dòng." },
            { l: 6, out: "Thanh tien: 50000 dong", why: "<code>2 * 25000</code> nằm ngoài dấu ngoặc kép nên máy tính ra 50000 rồi mới in. Dấu cách trong chuỗi vẫn được in." },
            { l: 7, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "Mỗi endl xuống một dòng; phép tính ngoài dấu ngoặc kép được tính ra 50000.",
          why: "Mỗi endl xuống một dòng, phép tính ngoài dấu ngoặc kép được tính ra 50000, và các dấu cách nằm trong chuỗi vẫn được in." },
        { id: "c1-dc2", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc1",
          title: "Lần 2 · Gán lại số ly",
          prompt: "Dòng 5 tính tổng tiền cho 3 ly trà đào (20000 đồng/ly). Sau đó dòng 6 gán lại <code>soLy</code> thêm 1 ly.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: GAN_LAI, focus: [5, 6], options: MAN_GAN, answer: MAN_GAN[0],
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
            { l: 4, mem: ["soLy", "int", "3"], why: "Khai báo <code>soLy</code> và gán giá trị 3." },
            { l: 5, mem: ["tongTien", "int", "60000"], why: "Tính <code>soLy * 20000</code> = 3 × 20000 = 60000 và lưu vào <code>tongTien</code> <strong>ngay lúc này</strong>." },
            { l: 6, mem: ["soLy", "int", "4"], why: "Gán lại: lấy giá trị cũ của <code>soLy</code> (3) cộng 1, được 4. Chỉ <code>soLy</code> đổi; <code>tongTien</code> vẫn là 60000 vì không có phép gán nào cho nó." },
            { l: 7, out: "So ly: 4\n", why: "In giá trị hiện tại của <code>soLy</code> là 4." },
            { l: 8, out: "Tong tien: 60000", why: "In giá trị hiện tại của <code>tongTien</code> là 60000." },
            { l: 9, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "tongTien được tính ở dòng 5 khi soLy còn là 3; dòng 6 chỉ đổi soLy.",
          why: "tongTien được tính một lần ở dòng 5 (khi soLy = 3), nên vẫn là 60000. Dòng 6 chỉ đổi soLy thành 4; biến không tự tính lại." },
        { id: "c1-dc3", type: "doanchay", predict: true, icon: "🔮", after: "c1-dc2",
          title: "Lần 3 · Khách gõ 4",
          prompt: "Chương trình hỏi số ly trà đào rồi tính tiền. Khi máy chờ ở dòng 6, khách gõ <code>4</code> rồi bấm Enter.",
          ask: "Theo bạn, màn hình sẽ hiện gì?",
          code: HOI_SO_LY, focus: [5, 6], input: "4",
          options: [manHoi(4), "Tong tien: 80000", "Nhap so ly: 4\nTong tien: soLy * 20000", "Nhap so ly: Tong tien: 80000"], answer: manHoi(4),
          trace: [
            { l: 3, why: "Máy bắt đầu chạy từ hàm <code>main()</code>." },
            { l: 4, mem: ["soLy", "int", "?"], why: "Khai báo <code>soLy</code>, chưa có giá trị." },
            { l: 5, out: "Nhap so ly: ", why: "In câu dẫn." },
            { l: 6, nhap: "4", mem: ["soLy", "int", "4"], why: "Khách gõ <code>4</code> rồi bấm Enter: số 4 hiện sau câu dẫn, con trỏ xuống dòng, <code>soLy</code> = 4." },
            { l: 7, out: "Tong tien: 80000", why: "Tính 4 × 20000 = 80000 rồi in." },
            { l: 8, why: "<code>return 0;</code> kết thúc chương trình." }],
          whyRight: "Câu dẫn, số 4 khách gõ, xuống dòng, rồi tổng tiền 80000.",
          why: "Màn hình có câu dẫn, số 4 khách gõ (Enter đưa con trỏ xuống dòng), rồi tổng tiền 4 × 20000 = 80000." },
        { id: "c1-bien", type: "choice", icon: "🔍", title: "Sau dòng 6, biến lưu gì?",
          prompt: "Ở chương trình Lần 2, ngay sau khi máy chạy xong dòng 6, hai biến <code>soLy</code> và <code>tongTien</code> đang lưu giá trị nào?",
          options: [
            { text: "soLy = 4, tongTien = 60000" },
            { text: "soLy = 4, tongTien = 80000", why: "tongTien chỉ đổi khi có phép gán cho nó. Dòng 6 chỉ gán cho soLy." },
            { text: "soLy = 3, tongTien = 60000", why: "Dòng 6 gán lại soLy = 3 + 1 = 4." },
            { text: "soLy = 1, tongTien = 20000", why: "soLy = soLy + 1 lấy giá trị cũ (3) cộng 1, không đặt lại về 1." }
          ],
          answer: "soLy = 4, tongTien = 60000",
          why: "Đúng. Dòng 6 chỉ đổi soLy; tongTien vẫn giữ giá trị đã tính ở dòng 5." },
        { id: "c1-dungsai", type: "truefalse", icon: "✅", title: "Đúng hay sai?",
          prompt: "Chọn Đúng hoặc Sai cho từng nhận xét ôn tập.",
          items: [
            { text: "<code>cout &lt;&lt; \"2 * 25000\";</code> in ra <code>50000</code>.", answer: false, why: "Trong dấu ngoặc kép là chuỗi nên máy in nguyên văn 2 * 25000." },
            { text: "Muốn hai câu nằm trên hai dòng, câu lệnh in câu thứ nhất cần <code>&lt;&lt; endl</code>.", answer: true },
            { text: "Câu lệnh <code>cin &gt;&gt; soLy;</code> phải đứng sau câu lệnh khai báo <code>int soLy;</code>.", answer: true },
            { text: "Tên biến <code>so ly</code> hợp lệ vì có nghĩa rõ ràng.", answer: false, why: "Tên biến không được có dấu cách: viết soLy hoặc so_ly." }
          ] },
        { id: "c1-loi", type: "line", icon: "🐛", title: "Bấm vào dòng có lỗi",
          prompt: "Bạn Hà viết chương trình hỏi số ly, nhưng máy báo không biết một tên biến. Bấm vào dòng có lỗi.",
          code: LOI_C1, answer: [6], wrongWhy: "So từng chữ của tên biến với dòng khai báo, kể cả chữ hoa và chữ thường.",
          why: "Đúng. Dòng 6 viết soly (chữ l thường) trong khi biến khai báo là soLy. C++ phân biệt chữ hoa và chữ thường." },
        { id: "c1-dien", type: "fill", icon: "✏️", title: "Điền vào chỗ trống",
          prompt: "Quầy cần in dòng <code>Tong tien: 75000</code> cho 3 ly trà sữa (25000 đồng/ly). Điền vào 2 chỗ trống.",
          template: `int soLy = 3;\ncout << "Tong tien: " [[0]] soLy [[1]] 25000;`,
          blanks: [
            { answers: ["<<"], options: ["<<", ">>", "+", ";"], why: "Các phần của câu lệnh cout nối bằng <<." },
            { answers: ["*"], options: ["+", "-", "*", "/"], why: "Tổng tiền = số ly nhân giá một ly." }
          ],
          screen: "Tong tien: 75000" },
        { id: "c1-viet", type: "code", icon: "🛠️", title: "Tự viết: hoá đơn trà đào",
          prompt: "Viết chương trình hỏi số ly trà đào rồi in hoá đơn 2 dòng. Làm theo 3 dòng chú thích trong khung.",
          card: {
            boiCanh: "Trà đào giá 20000 đồng một ly. Quầy cần chương trình hỏi khách mua mấy ly, rồi in số ly và tổng tiền trên hai dòng.",
            bien: [["int soLy;", "int", "số ly khách mua (đã khai báo)"]],
            nhap: "In câu dẫn <code>Nhap so ly: </code> rồi <code>cin &gt;&gt; soLy;</code>",
            xuLy: "Tổng tiền = <code>soLy * 20000</code>.",
